// EverGrandeCity_DrakesRoom (zone 51): generated by converter/gen_interiors.py from Sapphire's simple people and signs.
// Messages: src/text/script/0060_room_EverGrandeCity_DrakesRoom.txt
#include "asm/field_script.inc"
#include "hoenn.h"  // ch11
#include "hoenn_trainers.h"  // ch11 (before hoenn_story.inc: its macros name trainers)
#include "hoenn_story.inc"  // ch11

    ScriptEntry Script_None
    ScriptEntry DR_Drake  // 2: EverGrandeCity_DrakesRoom_EventScript_Drake  // story:
    ScriptEntry DR_Init  // 3: zone init (EverGrandeCity_DrakesRoom_OnLoad: the doors)  // story:
    ScriptEntry DR_WalkIn  // 4: OnFrame VAR_ELITE_4_STATE 3: ..._EventScript_WalkInCloseDoor  // story:
    ScriptEntriesEnd

Script_None:
    VMHalt
    .balign 4, 0

// ---- story (chapter Ch11, ch11 agent 2026-10-07; Sapphire data/maps/EverGrandeCity_DrakesRoom/scripts.inc and data/scripts/elite_four.inc;
// generators must keep everything from this line on; entries above marked "// story:")
// Scripts 2-4, text lines 1-2 (line 0 is the generator's). Room tiles = Sapphire tiles + (1,-1). Drake (uid 1, (6,5), model 89)
// is placed by data/story/ch11.json.
// The doors (Sapphire: setmetatile): the room's two warps are the doors, the entrance (warp 0, Sapphire (6,13)) and the exit
// (warp 1, Sapphire (6,2), room tile (7,1)). The exit's warp is moved off the map (ObjInitWarpGPos) until Drake is beaten, the
// entrance's once you have walked in (VAR_ELITE_4_STATE 4) or beaten Drake. The door models stay as the room builder made them.
// playbgm MUS_ENCOUNTER_ELITE_FOUR: with the Hoenn music answer only (h_playbgm_hoenn; Unova: the room's music goes on).
// Not ported: the spotlight metatiles that go dark (the room has none).
#define T_IntroSpeech 1
#define T_PostBattleSpeech 2
#define DR_ENTRY_WARP 0
#define DR_EXIT_WARP 1

DR_Drake:                                   // EverGrandeCity_DrakesRoom_EventScript_Drake
    ActorsPauseAll
    SEPlay SEQ_SE_MESSAGE
    ActorSetEyeToEye
    h_goto_if_set FLAG_DEFEATED_ELITE_4_DRAKE, L_DR_PostBattle
    h_playbgm_hoenn MUS_HOENN_ENCOUNTER_ELITE_FOUR    // Sapphire: playbgm MUS_ENCOUNTER_ELITE_FOUR
    h_msgbox T_IntroSpeech                     // intro (the in-battle defeat line is the trainer's message 1)
    h_closemessage
    h_setflag FLAG_E4_BATTLE_PENDING           // (cleared when won; still set after a whiteout: the League lobby resets the Elite Four)
    h_trainerbattle TRAINER_DRAKE
    h_clearflag FLAG_E4_BATTLE_PENDING
    h_setflag FLAG_DEFEATED_ELITE_4_DRAKE
    WorkSetConst 0x8004, 0                     // special sub_810FF60: the Fan Club counts the win
#if __has_include("common/fan_club.inc")
    VMCall Sub_FanClub_CountWin
#endif
    VMCall DR_SetAdvanceToNextRoom
    h_msgbox T_PostBattleSpeech
    h_release
L_DR_PostBattle:                            // ..._EventScript_PostBattleSpeech
    h_msgbox T_PostBattleSpeech
    h_release

DR_SetAdvanceToNextRoom:                    // PokemonLeague_EliteFour_SetAdvanceToNextRoomMetatiles
    h_applymovement 255, Common_Movement_Delay32
    h_waitmovement
    SEPlay SEQ_SE_KAIDAN                       // SE_DOOR (stand-in)
    ObjInitWarpGPos DR_EXIT_WARP, 7, 0, 1   // the exit door opens: warp 1 back at Sapphire (6,2) = room tile (7,1)
    VMReturn

DR_WalkIn:                                  // ..._EventScript_WalkInCloseDoor (PokemonLeague_EliteFour_EventScript_WalkInCloseDoor)
    ActorsPauseAll
    h_applymovement 255, Common_Movement_WalkUp6
    h_waitmovement
    SEPlay SEQ_SE_KAIDAN                       // SE_TRUCK_DOOR (stand-in)
    ObjInitWarpGPos DR_ENTRY_WARP, 0, 0, 0  // the entrance closes behind you
    h_setvar VAR_ELITE_4_STATE, 4
    h_release

DR_Init:                                    // ..._OnLoad (the zone init)
#ifdef HOENN_TEST_CH11
    VMCall Test_Ch11Start                      // test builds only (scenes/ch11_test.inc)
#endif
    h_goto_if_set FLAG_DEFEATED_ELITE_4_DRAKE, L_DR_Defeated     // ResetAdvanceToNextRoom: the exit open, the entrance closed
    ObjInitWarpGPos DR_EXIT_WARP, 0, 0, 0   // the exit door is shut
    h_goto_if_ne VAR_ELITE_4_STATE, 4, L_DR_InitDone
    ObjInitWarpGPos DR_ENTRY_WARP, 0, 0, 0  // CloseDoor
L_DR_InitDone:
    VMHalt
L_DR_Defeated:
    ObjInitWarpGPos DR_ENTRY_WARP, 0, 0, 0
    VMHalt

    .balign 4, 0
#include "common/movement.inc"
#if __has_include("common/fan_club.inc")
#include "common/fan_club.inc"
#endif
#include "scenes/ch11_test.inc"
